pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller1, address caller2, uint256 amount1, uint256 amount2) public {
        vm.assume(caller1 != address(0) && caller2 != address(0));
        vm.assume(caller1 != caller2);
        uint256 boundedAmount1 = bound(amount1, 1, 1e18);
        uint256 boundedAmount2 = bound(amount2, 1, 1e18);

        vm.deal(caller1, boundedAmount1);
        vm.deal(caller2, boundedAmount2);

        vm.prank(caller1);
        c.deposit{value: boundedAmount1}();
        vm.prank(caller2);
        c.deposit{value: boundedAmount2}();

        vm.prank(caller1);
        c.withdrawAll();
        vm.prank(caller2);
        c.withdrawAll();

        // After both withdrawalls: total credit of all users must equal contract balance
        // Since reference sets credit to 0, sum=0=balance; mutant keeps credit, sum>0 while balance=0
        assertTrue(c.credit(caller1) + c.credit(caller2) == address(c).balance);
    }
}

