pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 depositAmount, uint256 withdrawUser) public {
        vm.assume(depositAmount > 0 && depositAmount <= 1e18);
        vm.assume(withdrawUser <= 10);

        // Deposit some funds
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.deposit{value: depositAmount}();

        // Record the user's credit after deposit
        uint256 userCredit = c.credit(caller);

        // Call withdrawAll for a different user or same user
        address targetUser = (withdrawUser == 0) ? caller : address(uint160(withdrawUser * 1000 + 1));
        vm.prank(targetUser);
        (bool success, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));

        // The invariant: contract balance must be <= sum of all credits (we check for the specific caller)
        // Since we only have one caller in this test, the sum of credits is at least userCredit
        uint256 contractBalance = address(c).balance;
        assertTrue(contractBalance <= userCredit + (depositAmount - userCredit));
    }
}

